    Bug 1926443 - Use an enum value instead of a boolean in scrollSelectionIntoView. r=aleca,tobyp
    This argument changed to a short in 2010, but continued to compile because booleans are integers.
    It wasn't actually synchronous, as the enum value is 2 but true is 1, but I don't think it really matters.

    Differential Revision: https://phabricator.services.mozilla.com/D226571

diff --git a/mail/components/compose/content/dialogs/EdTableProps.js b/mail/components/compose/content/dialogs/EdTableProps.js
index 4e8235a287e..0b7b6d2c004 100644
--- a/mail/components/compose/content/dialogs/EdTableProps.js
+++ b/mail/components/compose/content/dialogs/EdTableProps.js
@@ -772,9 +772,9 @@ function MoveSelection(forward) {
   try {
     var selectionController = gActiveEditor.selectionController;
     selectionController.scrollSelectionIntoView(
-      selectionController.SELECTION_NORMAL,
-      selectionController.SELECTION_ANCHOR_REGION,
-      true
+      Ci.nsISelectionController.SELECTION_NORMAL,
+      Ci.nsISelectionController.SELECTION_ANCHOR_REGION,
+      Ci.nsISelectionController.SCROLL_SYNCHRONOUS
     );
   } catch (e) {}

